-- DIRECT Run Module, activity 'Open Module' (repository database).
-- Opens and evaluates one Module Instance; the rollback statement is returned, not executed.
-- Returns one row: MODULE_INSTANCE_ID, INTERNAL_PROCESSING_STATUS_CODE, MODULE_CODE and
--   MODULES (JSON array with the Module to run in the shape of omd.CreateBatchModuleInstances; empty unless 'Proceed').
-- Parameters: @ModuleCode, @ExecutionContext, @ModuleInstanceIdColumnName, @DefaultStartValue, @ConsistencyModuleTypeList, @SourceTimestampColumn.
SET NOCOUNT ON;

DECLARE @ModuleInstanceId BIGINT;
DECLARE @InternalProcessingStatusCode NVARCHAR(100);
DECLARE @RollbackStatement NVARCHAR(MAX);
DECLARE @SuccessIndicator CHAR(1) = 'N';
DECLARE @MessageLog NVARCHAR(MAX);
DECLARE @ErrorMessage NVARCHAR(2048);
DECLARE @ModuleId INT, @ModuleType NVARCHAR(100), @DataObjectSource NVARCHAR(1000);
DECLARE @ConsistencyDateTime DATETIME2(7), @ConsistencyDateTimeString NVARCHAR(27);
DECLARE @StartValue NVARCHAR(100) = COALESCE(NULLIF(TRIM(@DefaultStartValue), N''), N'1900-01-01');

EXEC [omd].[CreateModuleInstance]
   @ModuleCode        = @ModuleCode
  ,@ExecutionContext  = @ExecutionContext
  ,@ModuleInstanceId  = @ModuleInstanceId OUTPUT
  ,@SuccessIndicator  = @SuccessIndicator OUTPUT
  ,@MessageLog        = @MessageLog OUTPUT;

IF @SuccessIndicator <> 'Y' OR @ModuleInstanceId IS NULL
BEGIN
  SET @ErrorMessage = LEFT(N'DIRECT could not open Module ''' + COALESCE(@ModuleCode, N'') + N''': ' + COALESCE(@MessageLog, N''), 2048);
  THROW 50000, @ErrorMessage, 1;
END;

EXEC [omd].[ModuleEvaluation]
   @ModuleInstanceId               = @ModuleInstanceId
  ,@ModuleInstanceIdColumnName     = @ModuleInstanceIdColumnName
  ,@ExecuteRollbackIndicator       = 'N'
  ,@InternalProcessingStatusCode   = @InternalProcessingStatusCode OUTPUT
  ,@RollbackStatement              = @RollbackStatement OUTPUT
  ,@SuccessIndicator               = @SuccessIndicator OUTPUT
  ,@MessageLog                     = @MessageLog OUTPUT;

SET @InternalProcessingStatusCode = COALESCE(@InternalProcessingStatusCode, N'Abort');
SET @ModuleId = [omd].[GetModuleIdByModuleInstanceId](@ModuleInstanceId);

SELECT @ModuleType = MODULE_TYPE, @DataObjectSource = DATA_OBJECT_SOURCE FROM [omd].[MODULE] WHERE MODULE_ID = @ModuleId;

IF @InternalProcessingStatusCode = N'Proceed'
   AND @DataObjectSource IS NOT NULL
   AND EXISTS (SELECT 1 FROM STRING_SPLIT(COALESCE(@ConsistencyModuleTypeList, N''), ',') WHERE TRIM([value]) = @ModuleType)
BEGIN
  EXEC [omd].[GetConsistencyTimestamp]
     @TableList                   = @DataObjectSource
    ,@SourceTimestampColumn       = @SourceTimestampColumn
    ,@SourceModuleInstanceColumn  = @ModuleInstanceIdColumnName
    ,@SourceDataLookupIndicator   = 'N'
    ,@ConsistencyDateTime         = @ConsistencyDateTime OUTPUT;
  SET @ConsistencyDateTimeString = CASE WHEN @ConsistencyDateTime IS NULL THEN NULL ELSE FORMAT(@ConsistencyDateTime, 'yyyy-MM-dd HH:mm:ss.fffffff') END;
END;

DECLARE @Modules NVARCHAR(MAX) =
(
  SELECT
     CONVERT(BIGINT, 0) AS BATCH_INSTANCE_ID
    ,CONVERT(NVARCHAR(500), NULL) AS BATCH_CODE
    ,@ModuleInstanceId AS MODULE_INSTANCE_ID
    ,m.MODULE_ID
    ,m.MODULE_CODE
    ,m.MODULE_TYPE
    ,m.AREA_CODE
    ,1 AS [SEQUENCE]
    ,m.EXECUTABLE
    ,m.DATA_OBJECT_SOURCE
    ,m.DATA_OBJECT_TARGET
    ,COALESCE([omd].[GetModuleLoadWindowValue](m.MODULE_ID, 2), @StartValue) AS PREVIOUS_END_VALUE
    ,@InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE
    ,@RollbackStatement AS ROLLBACK_STATEMENT
    ,@ConsistencyDateTimeString AS CONSISTENCY_DATETIME
  FROM [omd].[MODULE] m
  WHERE m.MODULE_ID = @ModuleId
    AND @InternalProcessingStatusCode = N'Proceed'
  FOR JSON PATH
);

SELECT
   @ModuleInstanceId AS MODULE_INSTANCE_ID
  ,@InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE
  ,@ModuleCode AS MODULE_CODE
  ,COALESCE(@Modules, N'[]') AS MODULES;

-- DIRECT Run Batch / Run Module, activity 'Run Modules' (target engine, Fabric Warehouse).
-- Runs the Modules in @Modules (JSON array with the rows of omd.CreateBatchModuleInstances) in order.
-- Per Module: rollback statement (if any), load window end from the source data object, the executable through
-- sp_executesql with the parameters @ModuleInstanceId, @StartValue, @EndValue and @ConsistencyDateTime, and the
-- target row count before and after. One result row per Module, in the shape omd.EndBatchModuleInstances expects.
-- Parameters: @Modules (string, JSON), @LoadWindowAttributeName (string).
CREATE TABLE #modules
(
   [SEQ]                            INT
  ,[MODULE_INSTANCE_ID]             BIGINT
  ,[MODULE_CODE]                    VARCHAR(500)
  ,[EXECUTABLE]                     VARCHAR(8000)
  ,[DATA_OBJECT_SOURCE]             VARCHAR(1000)
  ,[DATA_OBJECT_TARGET]             VARCHAR(1000)
  ,[PREVIOUS_END_VALUE]             VARCHAR(100)
  ,[INTERNAL_PROCESSING_STATUS_CODE] VARCHAR(100)
  ,[ROLLBACK_STATEMENT]             VARCHAR(8000)
  ,[CONSISTENCY_DATETIME]           VARCHAR(100)
);

INSERT INTO #modules
SELECT
   ROW_NUMBER() OVER (ORDER BY [SEQUENCE], [MODULE_CODE])
  ,[MODULE_INSTANCE_ID], [MODULE_CODE], [EXECUTABLE], [DATA_OBJECT_SOURCE], [DATA_OBJECT_TARGET], [PREVIOUS_END_VALUE]
  ,[INTERNAL_PROCESSING_STATUS_CODE], [ROLLBACK_STATEMENT], [CONSISTENCY_DATETIME]
FROM OPENJSON(@Modules)
WITH
(
   [SEQUENCE]                       INT
  ,[MODULE_INSTANCE_ID]             BIGINT
  ,[MODULE_CODE]                    VARCHAR(500)
  ,[EXECUTABLE]                     VARCHAR(8000)
  ,[DATA_OBJECT_SOURCE]             VARCHAR(1000)
  ,[DATA_OBJECT_TARGET]             VARCHAR(1000)
  ,[PREVIOUS_END_VALUE]             VARCHAR(100)
  ,[INTERNAL_PROCESSING_STATUS_CODE] VARCHAR(100)
  ,[ROLLBACK_STATEMENT]             VARCHAR(8000)
  ,[CONSISTENCY_DATETIME]           VARCHAR(100)
)
WHERE [INTERNAL_PROCESSING_STATUS_CODE] = 'Proceed';

CREATE TABLE #results
(
   [Seq]              INT
  ,[ModuleInstanceId] BIGINT
  ,[ModuleCode]       VARCHAR(500)
  ,[EventCode]        VARCHAR(100)
  ,[StartValue]       VARCHAR(100)
  ,[EndValue]         VARCHAR(100)
  ,[RowCountInsert]   BIGINT
  ,[EventDetail]      VARCHAR(4000)
  ,[DurationMs]       INT
);

DECLARE @i INT = 0;
DECLARE @n INT = (SELECT COUNT(*) FROM #modules);
DECLARE @WindowColumn VARCHAR(128) = COALESCE(NULLIF(TRIM(@LoadWindowAttributeName), ''), 'INSCRIPTION_TIMESTAMP');
DECLARE @ParameterDefinition NVARCHAR(500) = N'@ModuleInstanceId BIGINT, @StartValue VARCHAR(100), @EndValue VARCHAR(100), @ConsistencyDateTime VARCHAR(100)';

DECLARE @ModuleInstanceId BIGINT, @ModuleCode VARCHAR(500), @Executable NVARCHAR(MAX), @Source VARCHAR(1000), @Target VARCHAR(1000);
DECLARE @StartValue VARCHAR(100), @EndValue VARCHAR(100), @Rollback NVARCHAR(MAX), @ConsistencyDateTime VARCHAR(100);
DECLARE @Sql NVARCHAR(MAX), @Before BIGINT, @After BIGINT, @T0 DATETIME2(6), @Step VARCHAR(50);

WHILE @i < @n
BEGIN
  SET @i = @i + 1;

  SELECT
     @ModuleInstanceId = [MODULE_INSTANCE_ID], @ModuleCode = [MODULE_CODE], @Executable = [EXECUTABLE]
    ,@Source = [DATA_OBJECT_SOURCE], @Target = [DATA_OBJECT_TARGET], @StartValue = [PREVIOUS_END_VALUE]
    ,@Rollback = [ROLLBACK_STATEMENT], @ConsistencyDateTime = [CONSISTENCY_DATETIME]
  FROM #modules
  WHERE [SEQ] = @i;

  SET @T0 = SYSDATETIME();
  SET @EndValue = NULL;
  SET @Before = NULL;
  SET @After = NULL;
  SET @Step = 'rollback';

  BEGIN TRY
    -- Rollback of earlier failed instances, decided by the Module evaluation in the repository
    IF @Rollback IS NOT NULL AND TRIM(@Rollback) <> ''
    BEGIN
      EXEC sp_executesql @Rollback;
    END;

    -- Load window end: the latest load window attribute value in the source data object.
    -- When the source has no such attribute (for example an operational source), the current time is used.
    SET @Step = 'load window';
    IF @Source IS NOT NULL AND TRIM(@Source) <> ''
    BEGIN
      BEGIN TRY
        SET @Sql = N'SELECT @e = CONVERT(VARCHAR(27), MAX(' + QUOTENAME(@WindowColumn) + N'), 121) FROM ' + @Source;
        EXEC sp_executesql @Sql, N'@e VARCHAR(27) OUTPUT', @e = @EndValue OUTPUT;
      END TRY
      BEGIN CATCH
        SET @EndValue = NULL;
      END CATCH;
    END;
    IF @EndValue IS NULL SET @EndValue = CONVERT(VARCHAR(27), SYSDATETIME(), 121);

    -- Target row count before
    SET @Step = 'row count';
    IF @Target IS NOT NULL AND TRIM(@Target) <> ''
    BEGIN
      BEGIN TRY
        SET @Sql = N'SELECT @c = COUNT_BIG(*) FROM ' + @Target;
        EXEC sp_executesql @Sql, N'@c BIGINT OUTPUT', @c = @Before OUTPUT;
      END TRY
      BEGIN CATCH
        SET @Before = NULL;
      END CATCH;
    END;

    -- The executable
    SET @Step = 'executable';
    EXEC sp_executesql @Executable, @ParameterDefinition
      ,@ModuleInstanceId = @ModuleInstanceId, @StartValue = @StartValue, @EndValue = @EndValue, @ConsistencyDateTime = @ConsistencyDateTime;

    -- Target row count after
    SET @Step = 'row count';
    IF @Before IS NOT NULL
    BEGIN
      BEGIN TRY
        SET @Sql = N'SELECT @c = COUNT_BIG(*) FROM ' + @Target;
        EXEC sp_executesql @Sql, N'@c BIGINT OUTPUT', @c = @After OUTPUT;
      END TRY
      BEGIN CATCH
        SET @After = NULL;
      END CATCH;
    END;

    INSERT INTO #results VALUES (@i, @ModuleInstanceId, @ModuleCode, 'Success', @StartValue, @EndValue, @After - @Before, NULL, DATEDIFF(MILLISECOND, @T0, SYSDATETIME()));
  END TRY
  BEGIN CATCH
    INSERT INTO #results VALUES (@i, @ModuleInstanceId, @ModuleCode, 'Failure', @StartValue, @EndValue, NULL,
      LEFT('Error in ' + @Step + ' (' + CONVERT(VARCHAR(20), ERROR_NUMBER()) + '): ' + ERROR_MESSAGE(), 4000), DATEDIFF(MILLISECOND, @T0, SYSDATETIME()));
  END CATCH;
END;

SELECT [Seq], [ModuleInstanceId], [ModuleCode], [EventCode], [StartValue], [EndValue], [RowCountInsert], [EventDetail], [DurationMs]
FROM #results
ORDER BY [Seq];

-- DIRECT Run Module, activity 'Close Module' (repository database).
-- Records the load window and the outcome of the Module Instance from the result row of 'Run Modules'.
-- Fails the activity (after the bookkeeping) when the Module failed.
-- Parameters: @ModuleInstanceId (string), @InternalProcessingStatusCode, @ModuleResults (string, JSON array with one row).
SET NOCOUNT ON;

DECLARE @Id BIGINT = TRY_CONVERT(BIGINT, NULLIF(TRIM(@ModuleInstanceId), N''));
DECLARE @EventCode NVARCHAR(100), @StartValue NVARCHAR(100), @EndValue NVARCHAR(100), @RowCountInsert BIGINT, @EventDetail NVARCHAR(4000);
DECLARE @SuccessIndicator CHAR(1) = 'N';
DECLARE @MessageLog NVARCHAR(MAX);
DECLARE @ErrorMessage NVARCHAR(2048);

IF @Id IS NULL OR @InternalProcessingStatusCode <> N'Proceed'
BEGIN
  -- The Module Instance was closed by its evaluation (Cancel or Abort); nothing to report.
  SELECT @Id AS MODULE_INSTANCE_ID, @InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE, NULL AS EVENT_CODE;
  RETURN;
END;

SELECT TOP 1
   @EventCode      = COALESCE(NULLIF(TRIM([EventCode]), N''), N'Failure')
  ,@StartValue     = NULLIF(TRIM([StartValue]), N'')
  ,@EndValue       = NULLIF(TRIM([EndValue]), N'')
  ,@RowCountInsert = COALESCE([RowCountInsert], 0)
  ,@EventDetail    = [EventDetail]
FROM OPENJSON(NULLIF(TRIM(@ModuleResults), N''))
WITH
(
   [ModuleInstanceId] BIGINT
  ,[EventCode]        NVARCHAR(100)
  ,[StartValue]       NVARCHAR(100)
  ,[EndValue]         NVARCHAR(100)
  ,[RowCountInsert]   BIGINT
  ,[EventDetail]      NVARCHAR(4000)
)
WHERE [ModuleInstanceId] = @Id;

IF @EventCode IS NULL
BEGIN
  SET @EventCode = N'Failure';
  SET @EventDetail = N'The orchestrator did not report a result for the Module Instance.';
END;

IF @StartValue IS NOT NULL
BEGIN
  EXEC [omd].[SetSourceControlValues] @ModuleInstanceId = @Id, @StartValue = @StartValue, @EndValue = @EndValue;
END;

IF @EventCode = N'Failure' AND @EventDetail IS NOT NULL
BEGIN
  EXEC [omd].[InsertIntoEventLog] @ModuleInstanceId = @Id, @EventDetail = @EventDetail;
END;

EXEC [omd].[UpdateModuleInstance]
   @ModuleInstanceId  = @Id
  ,@EventCode         = @EventCode
  ,@RowCountInsert    = @RowCountInsert
  ,@SuccessIndicator  = @SuccessIndicator OUTPUT
  ,@MessageLog        = @MessageLog OUTPUT;

SELECT @Id AS MODULE_INSTANCE_ID, @InternalProcessingStatusCode AS INTERNAL_PROCESSING_STATUS_CODE, @EventCode AS EVENT_CODE;

IF @SuccessIndicator <> 'Y'
BEGIN
  SET @ErrorMessage = LEFT(N'DIRECT could not close Module Instance ' + CONVERT(NVARCHAR(20), @Id) + N': ' + COALESCE(@MessageLog, N''), 2048);
  THROW 50000, @ErrorMessage, 1;
END;

IF @EventCode = N'Failure'
BEGIN
  SET @ErrorMessage = LEFT(N'Module Instance ' + CONVERT(NVARCHAR(20), @Id) + N' failed: ' + COALESCE(@EventDetail, N'no detail'), 2048);
  THROW 50000, @ErrorMessage, 1;
END;

-- DIRECT Run Module, activity 'Fail Module' (repository database). Runs when 'Run Modules' itself failed.
-- Fails the Module Instance, logs the error, then fails when @RaiseError = 'Y'.
-- Parameters: @ModuleInstanceId (string), @InternalProcessingStatusCode, @ErrorMessage (string), @RaiseError (string, 'Y' or 'N').
SET NOCOUNT ON;

DECLARE @Id BIGINT = TRY_CONVERT(BIGINT, NULLIF(TRIM(@ModuleInstanceId), N''));
DECLARE @Detail NVARCHAR(4000) = LEFT(N'The orchestrator failed to run the Module: ' + COALESCE(@ErrorMessage, N'no error message'), 4000);
DECLARE @Message NVARCHAR(2048) = LEFT(@Detail, 2048);

IF @Id IS NOT NULL AND @InternalProcessingStatusCode = N'Proceed'
BEGIN
  EXEC [omd].[InsertIntoEventLog] @ModuleInstanceId = @Id, @EventDetail = @Detail;
  EXEC [omd].[UpdateModuleInstance] @ModuleInstanceId = @Id, @EventCode = N'Failure';
END;

IF UPPER(COALESCE(@RaiseError, N'Y')) = N'Y' THROW 50000, @Message, 1;

SELECT @Id AS INSTANCE_ID, N'Failure' AS EVENT_CODE;
